"""Reconcile memory symbolic and wrapper packaging authority without erasing historical rejected designs."""
from pathlib import Path
import json,hashlib
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-task-research-rev1'
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def ref(p):return dict(path=Path(p).as_posix(),sha256=hashlib.sha256(Path(p).read_bytes()).hexdigest())
def save(n,v):
 p=O/n
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
notes={'CAMPAIGN2_TASK_COMMITMENT_DRAFT.md': 'Initial unaccepted lifecycle draft; retain all TC-A..L and concrete/non-Need/observer-safe distinctions, not runtime evidence. Reuses authored task referents distinct from holder/prototype; point evidence may be fallible, never truth/social fulfillment/causal success. Missing state originally errors/exact all-key domain and DeadlineMissed deadline payload are superseded by subset adoption/absentNoChange and immutable-spec deadline, not duplicate status field. Initially proposed priority becomes half-open immutable-target disjointness/full-stage collision seal, not first-writer arbitration. Later empty semantic output closure supersedes undecided retirement output; trace remains forbidden cognitive input. Unused retirement causes are not enum aliases. Need-shaped/immortal/stakeholder negatives and historical live-list pressure comparison persist. Lifecycle has no RNG/PERSIST-I, later workspace/planning/identity not implied. Broader reopen conditions remain obligations, not automatically current owner blockers.', 'CAMPAIGN2_TASK_MOTIVE_OPTION_BRIDGE_RESEARCH.md': 'Research direction keeps prediction-versus-action-efficacy gap explicit. Initially adopted procedural instruction means what to try, not chosen intent/skill/efficacy probability/success. Availability is not adoption; no mapping from interval sign/task spelling/registry order/world magnitude. Separate owned plan state persists through status replacement, no terminal resurrection; later accepted immutable instruction map and action-origin union deduplication answer shape alternatives. Missing plan can leave motive but no option; no default lottery ticket or truth feasibility query. Positive base pressure independent of concern/forecast; concern is non-generating modifier with original observation support, not independent concern occurrence/confidence. Base adopted-context provenance traced and unique per task/option despite empty observation basis. Actual attempt and world interference stay separate. Identity exploration is only a component possibility, not generated path. Dynamic plans/learned efficacy/general planner/skill/social/causal attribution remain unqualified by this procedural candidate; phase60/70/80 are historical schedule, not current universal phase law.', 'CAMPAIGN2_GOAL_APPRAISAL_RESEARCH_TARGET.md': 'Unaccepted research intake, not implemented authority. Same forecast changes relevance under goal while forecast has no intrinsic valence. Distinct workspace/appraisal/transient affect/motive owners; no Need-shaped goal or affect action command. Prior committed366 requires actual admitted downstream producer; character accessibility alone not admission/current-lane belief update. Historical four live-list tests externally supplied active commitments, not actual lifecycle. Preserve MEC020/EXP013, RET010/011 negativecontrols; workspace/salience separate, unknown not zero, no censored surprise/precisioncredit/Overflow/currenttruth. Reason/dice/expression/identity chain and TRC004 provenance stay mandatory; no automatic51/52feedback. Initial authored importance ambiguity corrected by task contract to goal facts with separate versioned calibration, not raw psychology. Discrepancy is not fear/control/efficacy and transient conclusion earns no persistent affect field. Nine comparison obligations retain goal/forecast/unknown/retirement/recurrence/truth/ablation/arbitration/cause distinctions with scoped later crosswalks. Second content kind must compile independently without qualifying tasks as Character or weakening frozen one-kind models. Authored procedure cannot supply efficacy belief; explicit adopted procedural context later answers bounded option-source gap, not general learned efficacy.'}
notes={(P/k).as_posix():v for k,v in notes.items()}
ip=P/'campaign3-history-source-roles-rev224/index.json';ix=load(ip);entries={x['path']:x for x in load(B/'manifest.json')['entries']}
chain=[ref(P/'campaign3-history-task-packaging-rev1/review.json'),ref(P/'campaign3-history-task-lifecycle-rev1/review.json'),ref(P/'campaign3-history-cognitive-reason-contracts-rev1/review.json'),ref(P/'campaign3-history-cognitive-appraisal-rev2/crosswalk.json')]
sources=[]
for p,n in notes.items():
 assert p in ix['unassignedCandidatePaths'] and ref(p)['sha256']==entries[p]['sha256']
 sources.append(dict(**ref(p),role='HISTORICAL TASK RESEARCH TARGET WITH SUPERSEDED PROPOSALS AND RETAINED PHENOMENA',judgment=n,acceptanceChain=chain))
rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source'] not in notes:continue
  assert u['sourceSha256']==entries[u['source']]['sha256']
  rows.append(dict(occurrenceId=u['id'],source=u['source'],sourceSha256=u['sourceSha256'],location=u['location'],text=u['text'],category='NARRATIVE'))
assert len({x['occurrenceId'] for x in rows})==len(rows)
O.mkdir(exist_ok=True)
save('review.json',dict(status='THREE TASK RESEARCH SOURCES RECONCILED',checker=ref(__file__),sourceIndex=ref(ip),sourceRoles=sources,rows=rows,preservedArtifacts=[],limits=['Historical target proposals are not current qualification; later accepted topology/phase contracts govern their models.','Procedural instruction is not an efficacy estimate, chosen intent or learned plan; wider phenomena remain separate obligations.','Initial exact-key/deadline-payload/importance proposals are explicitly superseded, with original text retained.','No runtime/test/build rerun, new source gap/archive, model, allocation, verdict, corpus or obligation status change. Adequacy remains open.'],obligations=['RO-C3-008','RO-C3-019','RO-C3-020','RO-C3-021']))
save('check.json',dict(status='PASS TASK RESEARCH HISTORY',sources=3,originalNarrativeOccurrences=len(rows),originalBackingOccurrences=0,review=ref(O/'review.json')))
assert all(p.stat().st_size<50000000 for p in O.iterdir())
print(json.dumps(load(O/'check.json')))
